# Source for q/ae-care2.js: Clinical care (history, labs, ECG, murmurs, medications, emergencies, safety, communication).
CC="Clinical care"
Q=[
# --- Labs ---
(CC,"An elevated BNP (B-type natriuretic peptide) suggests:","Heart failure with raised ventricular wall stress",["Kidney stones","Normal heart function","Pulmonary embolism only"],"BNP and NT-proBNP rise when the ventricles are stretched by high pressure or volume.","F"),
(CC,"A rising troponin level indicates:","Myocardial injury, such as from myocardial infarction",["Heart failure only","Infection","Normal aging"],"Echo then looks for regional wall motion abnormalities and complications.","F"),
(CC,"A negative D-dimer test is useful because it:","Makes pulmonary embolism or DVT unlikely in low-risk patients",["Confirms pulmonary embolism","Diagnoses heart failure","Shows LV thrombus"],"D-dimer is sensitive but not specific; many conditions raise it.","F"),
(CC,"The usual therapeutic INR range for a patient on warfarin for atrial fibrillation is:","2.0 to 3.0",["0.5 to 1.0","4.0 to 6.0","1.0 only"],"Some mechanical mitral valves need a higher target, about 2.5 to 3.5. Check INR before TEE or other procedures.","F"),
(CC,"Severe anemia can cause which echo finding?","A high-output state with increased flow velocities and flow murmurs",["Low-output state","Aortic stenosis","Pericardial thickening"],"Low viscosity and high cardiac output raise velocities across normal valves.","F"),
(CC,"Before an echo for suspected endocarditis, which lab result is most relevant?","Blood cultures",["Cholesterol","Hemoglobin A1c","Urinalysis"],"Positive cultures with typical organisms are a major Duke criterion.","F"),
(CC,"Hyperthyroidism can affect the heart by causing:","Atrial fibrillation, tachycardia and high-output state",["Bradycardia and pericardial thickening","Coarctation","Bicuspid valve"],"Hypothyroidism can cause bradycardia and pericardial effusion.","F"),
(CC,"Normal serum potassium is about:","3.5 to 5.0 mmol/L",["1.0 to 2.0 mmol/L","6.5 to 8.0 mmol/L","10 mmol/L"],"Abnormal potassium can cause dangerous arrhythmias, important during stress testing.","C"),
# --- ECG ---
(CC,"An irregularly irregular rhythm without P waves is:","Atrial fibrillation",["Sinus rhythm","Atrial flutter","Complete heart block"],"The mitral A wave is absent on Doppler in AF.","F"),
(CC,"A 'sawtooth' baseline on the ECG suggests:","Atrial flutter",["Atrial fibrillation","Sinus tachycardia","Ventricular tachycardia"],"Flutter waves may create small, regular atrial contractions on Doppler.","F"),
(CC,"Left bundle branch block on ECG commonly causes which echo finding?","Abnormal (dyssynchronous) septal motion",["Pericardial effusion","Mitral stenosis","RV hypertrophy"],"The septum contracts early ('septal flash'), which can be mistaken for ischemia.","F"),
(CC,"A ventricular paced rhythm commonly produces:","Abnormal septal motion",["Normal septal motion always","Aortic stenosis","Coarctation"],"The RV lead activates the septum first. Look for the pacing wire in the RV.","F"),
(CC,"ST-segment elevation in a group of leads with chest pain suggests:","Acute myocardial infarction (STEMI)",["Normal finding","Mitral stenosis","Pulmonic stenosis"],"Report new wall motion abnormalities immediately.","F"),
(CC,"Low QRS voltage on the ECG with thick LV walls on echo suggests:","Cardiac amyloidosis",["Hypertensive heart disease","Athlete's heart","Normal finding"],"Hypertensive LVH usually shows high voltages.","F"),
(CC,"Measurements of Doppler velocities should avoid the beat right after a premature ventricular contraction because:","The post-PVC beat has a longer filling time and a stronger contraction, inflating velocities",["It has no flow","It is always aliased","It is the most accurate beat"],"Choose representative beats in regular rhythm.","F"),
(CC,"Complete heart block on the ECG shows:","P waves and QRS complexes that are unrelated to each other",["No P waves","A short PR interval","An irregularly irregular rhythm"],"Atrial contractions may fall at random times relative to ventricular filling.","F"),
(CC,"A short PR interval with a delta wave suggests:","Wolff-Parkinson-White syndrome",["Atrial fibrillation","Heart block","LV hypertrophy"],"An accessory pathway can cause abnormal septal motion and fast arrhythmias.","C"),
(CC,"Sinus bradycardia is a heart rate below:","60 beats per minute",["100 beats per minute","40 beats per minute only","80 beats per minute"],"Athletes and patients on beta-blockers often have resting bradycardia.","F"),
(CC,"A wide-complex tachycardia during a stress test should be treated as:","Possible ventricular tachycardia, so stop the test and get help",["Normal response","Sinus tachycardia","A sign of good fitness"],"Sustained VT is an absolute reason to stop.","F"),
# --- History and murmurs ---
(CC,"Syncope during exertion in an older patient with a systolic murmur suggests:","Severe aortic stenosis",["Mitral valve prolapse","Pericarditis","Atrial septal defect"],"HCM is a common cause in younger patients.","F"),
(CC,"A crescendo-decrescendo systolic murmur at the right upper sternal border radiating to the carotids suggests:","Aortic stenosis",["Mitral regurgitation","Aortic regurgitation","Mitral stenosis"],"Severe AS can soften the second heart sound.","F"),
(CC,"A holosystolic murmur at the apex radiating to the axilla suggests:","Mitral regurgitation",["Aortic stenosis","Tricuspid stenosis","Pulmonic regurgitation"],"Echo assesses mechanism and severity.","F"),
(CC,"A decrescendo diastolic murmur along the left sternal border suggests:","Aortic regurgitation",["Mitral regurgitation","Aortic stenosis","VSD"],"It is heard best with the patient sitting forward at end-expiration.","F"),
(CC,"A low-pitched diastolic rumble at the apex with an opening snap suggests:","Mitral stenosis",["Aortic stenosis","Mitral valve prolapse","HCM"],"The opening snap comes from the stiff mitral leaflets snapping open.","F"),
(CC,"A continuous 'machinery' murmur under the left clavicle suggests:","Patent ductus arteriosus",["Mitral stenosis","ASD","Aortic stenosis"],"Flow from aorta to pulmonary artery continues through systole and diastole.","F"),
(CC,"A systolic murmur that gets louder with Valsalva strain or standing suggests:","Hypertrophic obstructive cardiomyopathy",["Aortic stenosis","Mitral stenosis","Aortic regurgitation"],"Reducing preload increases LVOT obstruction. Most other murmurs get softer.","F"),
(CC,"A mid-systolic click followed by a late systolic murmur suggests:","Mitral valve prolapse",["Aortic regurgitation","Pericarditis","PDA"],"The click occurs as the prolapsing leaflet tenses.","F"),
(CC,"A patient with a stroke is referred for echo mainly to look for:","A cardiac source of embolism, such as LA thrombus, PFO, vegetation or tumor",["Aortic root size only","LV hypertrophy only","Coronary calcium"],"A bubble study and TEE are often added.","F"),
(CC,"In a normal pregnancy, the heart typically shows:","Higher cardiac output and heart rate, with mild chamber enlargement",["Reduced cardiac output","Severe LV dysfunction","Aortic stenosis"],"Cardiac output rises by about 30% to 50%. A small effusion and trace regurgitation can be normal.","F"),
(CC,"A patient receiving anthracycline chemotherapy needs an echo to:","Monitor LV function and GLS for cardiotoxicity",["Check for bicuspid valve","Measure coronary flow","Assess the aortic arch only"],"Compare with the baseline study using the same methods.","F"),
(CC,"Which history finding raises concern for aortic dissection?","Sudden tearing chest pain radiating to the back",["Gradual exertional chest pressure","Fever and night sweats","Leg swelling only"],"Treat as an emergency and alert the physician.","F"),
(CC,"A family history of sudden cardiac death in a young relative should prompt a careful look for:","HCM, ARVC and other inherited cardiomyopathies",["Mitral annular calcification","Lambl's excrescences","Aortic atheroma"],"Screening of first-degree relatives is often recommended.","F"),
(CC,"A tall, thin patient with long limbs and a family history of aortic dissection should be checked for:","Marfan syndrome: aortic root dilation and MVP",["Tetralogy of Fallot","Ebstein anomaly","Carcinoid"],"Measure the root at the sinuses carefully.","F"),
# --- Medications ---
(CC,"Beta-blockers can affect a stress echo by:","Blunting the heart rate response, making target heart rate harder to reach",["Raising heart rate","Causing aortic stenosis","Increasing contractility"],"Some labs ask patients to hold beta-blockers before stress testing, per physician instructions.","F"),
(CC,"Nitrates affect the heart mainly by:","Reducing preload through venous dilation",["Increasing afterload","Raising heart rate dramatically","Causing pericardial effusion"],"Reduced preload can worsen LVOT obstruction in HCM.","F"),
(CC,"Diuretics can change diastolic Doppler patterns by:","Lowering preload, which can make a pseudonormal pattern look like impaired relaxation",["Raising LA pressure","Causing aortic regurgitation","Lengthening the QRS"],"Filling patterns depend on volume status at the time of the study.","C"),
(CC,"Before TEE in a patient on anticoagulants, the team should consider:","Bleeding risk, especially with esophageal varices or recent esophageal surgery",["Stopping all monitoring","Giving more anticoagulant","Removing ECG leads"],"Follow the physician's instructions about anticoagulation.","F"),
(CC,"Atropine during dobutamine stress echo should be avoided in patients with:","Narrow-angle glaucoma or urinary obstruction",["Hypertension controlled with medication","A previous normal echo","Sinus rhythm"],"Atropine can worsen glaucoma and urinary retention.","C"),
(CC,"The reversal agent for benzodiazepine sedation (such as midazolam) is:","Flumazenil",["Naloxone","Atropine","Epinephrine"],"Naloxone reverses opioids such as fentanyl.","C"),
(CC,"Naloxone is used to reverse:","Opioid-induced respiratory depression",["Benzodiazepine sedation","Beta-blocker effects","Allergic reactions"],"Fentanyl and morphine are common opioids used for sedation.","C"),
(CC,"Inotropes such as dobutamine increase:","Contractility and heart rate",["Preload only","Afterload only","Blood viscosity"],"This is why dobutamine is used for stress echo and low-flow AS evaluation.","F"),
# --- Emergencies ---
(CC,"For an adult in cardiac arrest, chest compressions should be delivered at a rate of:","100 to 120 per minute",["60 to 80 per minute","150 to 180 per minute","30 per minute"],"Compress at least 2 inches (5 cm) deep and allow full recoil.","F"),
(CC,"The first step when a patient collapses during an exam is to:","Check responsiveness and breathing, and call for help and an AED",["Finish the exam","Leave to find the physician","Give water"],"Start CPR if the patient is unresponsive and not breathing normally.","F"),
(CC,"Signs of anaphylaxis after contrast include:","Hives, wheezing, throat swelling and low blood pressure",["Mild warmth only","Increased appetite","Bradycardia only"],"Stop the infusion, call for help and prepare epinephrine per protocol.","F"),
(CC,"The first-line medication for anaphylaxis is:","Epinephrine",["Atropine","Flumazenil","Aspirin"],"Antihistamines and steroids are secondary treatments.","F"),
(CC,"The FAST acronym for stroke signs stands for:","Face drooping, Arm weakness, Speech difficulty, Time to call for help",["Fever, Anemia, Shock, Tachycardia","Fainting, Ache, Sweating, Thirst","Fluid, Air, Sound, Temperature"],"Rapid recognition is critical, especially during or after TEE or catheter procedures.","F"),
(CC,"A diabetic patient becomes sweaty, shaky and confused while waiting. The likely problem is:","Hypoglycemia",["Hyperthyroidism","Normal anxiety","Tamponade"],"Check blood glucose and give fast-acting sugar if the patient can swallow safely.","F"),
(CC,"If a patient has a seizure on the exam table, the sonographer should:","Protect the patient from injury, not restrain them, and call for help",["Hold the patient down firmly","Put an object in the mouth","Leave the room"],"Turn the patient on their side afterward to protect the airway.","F"),
(CC,"A patient develops chest pain during a resting echo. The sonographer should:","Stop, stay with the patient, call for help and notify the physician",["Continue scanning silently","Send the patient home","Give nitroglycerin without orders"],"Record images of any new wall motion abnormality if it is safe and quick.","F"),
(CC,"Oxygen given by nasal cannula is usually delivered at:","1 to 6 liters per minute",["20 to 30 liters per minute","0.1 liters per minute","Oxygen is never given by cannula"],"Higher flows need a face mask.","C"),
(CC,"Before moving a patient with an IV, the sonographer should check:","That the line is secure and the bag is kept above the IV site",["Nothing","That the IV is clamped permanently","That the bag is below the patient"],"Gravity drives IV fluids; lowering the bag can let blood back up the tubing.","F"),
(CC,"A patient on a ventilator in the ICU should be imaged:","Without disconnecting any lines, coordinating with nursing staff",["After removing the ventilator briefly","Only in the echo lab","Prone"],"Respiratory variation of the IVC is interpreted differently on a ventilator.","F"),
(CC,"In a mechanically ventilated patient, IVC size is:","Less reliable for estimating RA pressure because positive pressure changes the normal pattern",["The best indicator of RA pressure","Always small","Always collapsing"],"A small IVC still suggests low RA pressure, but a dilated IVC is common and non-specific.","C"),
# --- Safety, infection, equipment ---
(CC,"Disinfectant wipes must stay wet on the probe for:","The contact time specified by the manufacturer",["One second","No time; wipe and dry immediately","24 hours"],"Contact (dwell) time is what kills the organisms.","F"),
(CC,"TEE probes should be stored:","Hanging vertically in a clean, ventilated cabinet",["Coiled in a drawer","On the floor","In the patient's room"],"Hanging allows drying and avoids damage to the shaft.","F"),
(CC,"An automated endoscope reprocessor (AER) is used for:","Standardized high-level disinfection of TEE probes",["Cleaning the keyboard","Charging the battery","Sterilizing gel"],"Manual soaking is also allowed if done to the manufacturer's instructions.","C"),
(CC,"The ultrasound keyboard, cables and bed rails should be cleaned:","Between every patient",["Once a month","Only when visibly soiled","Never"],"Contaminated surfaces spread infections between patients.","F"),
(CC,"Bariatric patients may need:","A lower-frequency transducer, adjusted positioning and equipment rated for their weight",["The highest-frequency probe","No changes","Only TEE"],"Patient and staff safety come first; get help with positioning.","F"),
(CC,"A patient at high risk for falls should:","Have the bed lowered, rails up where appropriate and be helped on and off the table",["Climb onto the table alone","Stand during the exam","Be left unattended"],"Falls are among the most common patient injuries in imaging departments.","F"),
(CC,"Electrical safety in the echo lab includes:","Using grounded outlets, inspecting cords and reporting damaged equipment",["Using extension cords for every machine","Ignoring frayed cords","Using equipment with missing ground pins"],"Damaged insulation can cause leakage current to the patient.","F"),
# --- Communication, ethics, scope ---
(CC,"SBAR is a structured method for:","Communicating clinical information: Situation, Background, Assessment, Recommendation",["Cleaning transducers","Scoring wall motion","Grading valve disease"],"It helps report critical findings clearly to physicians.","F"),
(CC,"A patient asks the sonographer whether the echo is normal. The best response is:","Explain that the physician will review the images and discuss the results",["Give a full diagnosis","Say everything is fine","Refuse to speak"],"Interpreting results is outside the sonographer's scope.","F"),
(CC,"A patient who speaks limited English needs:","A qualified medical interpreter, not a family member, for consent and important instructions",["No explanation","A child to translate","Written English instructions only"],"Accurate communication protects the patient's rights and safety.","F"),
(CC,"Under HIPAA, the 'minimum necessary' rule means:","Only access and share the patient information needed for the task",["Share everything with everyone","Never share any information","Only share information by email"],"Avoid discussing patients in public areas.","F"),
(CC,"Documentation of an echo should include:","Patient identifiers, indication, technical quality, limitations and any communication of critical findings",["Only the final EF","Nothing written","Only images"],"Accurate records protect patients and staff.","F"),
(CC,"Acting outside the sonographer's scope of practice includes:","Prescribing medication or giving a final diagnosis to the patient",["Optimizing images","Measuring chambers","Reporting findings to the physician"],"Know and follow your institution's policies.","F"),
(CC,"A patient's right to privacy during the exam includes:","Proper draping and exposing only the area needed for scanning",["Leaving the door open","Discussing the case in the hallway","Uncovering the patient fully"],"Offer a chaperone according to facility policy.","F"),
(CC,"A sonographer finds a severe abnormality on a weekend outpatient study. The correct action is:","Follow the critical-results policy and contact the responsible physician directly",["Wait until Monday","Tell the patient the diagnosis","Leave a note on the report only"],"Document who was told, and when.","F"),
(CC,"Informed consent requires that the patient:","Understands the procedure, risks, benefits and alternatives, and agrees voluntarily",["Signs without reading","Is sedated before consenting","Has a family member decide even when competent"],"The physician performing the procedure is responsible for obtaining consent.","F"),
(CC,"When a patient arrives with a prior echo from another hospital, the sonographer should:","Review it to compare findings and focus the exam",["Ignore it","Copy its measurements into the new report","Refuse to scan"],"Comparison with prior studies is a key part of interpretation.","F"),
]
